int minprice = INT_MAX;
int max_profit = 0;
for (int i = 0; i < n; i++) {
    if (prices[i] < minprice)
        minprice = prices[i];
    else if (prices[i] - minprice > max_profit)
        max_profit = prices[i] - minprice;
}

for (int i = 0; i < n - 1; i++) {
    if (prices[i] < prices[i + 1])
        max_profit += prices[i + 1] - prices[i];
}
